parameters.jsCode:
const extraction = $('Check required').first().json.output;
const fields = extraction.missing_info.map(m => m.field);
const raw = $input.first().json['Answers'] || '';

const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
const answers = {};

lines.forEach((line, idx) => {
  const m = line.match(/^([a-z_]+)\s*:\s*(.*)$/);
  if (m && fields.includes(m[1])) {
    // format "field: value"
    if (m[2]) answers[m[1]] = m[2];
  } else if (fields[idx] !== undefined && answers[fields[idx]] === undefined) {
    // brak prefiksu → przypisz według kolejności pytań
    answers[fields[idx]] = line;
  }
});

const filled = { ...extraction };
for (const f of fields) {
  if (answers[f] === undefined) continue;
  filled[f] = typeof extraction[f] === 'number' ? Number(answers[f]) : answers[f];
}

const unresolved = extraction.missing_info.filter(m => answers[m.field] === undefined);
filled.missing_info = unresolved;
filled.human_review = {
  source: unresolved.length ? 'form_partial_or_timeout' : 'form',
  at: $now.toISO(),
  raw_answers: raw,
};

return [{ json: filled }];

const out = { ...$input.first().json.output };
out.missing_info = [...(out.missing_info || [])];

const REQUIRED = ['client', 'position', 'headcount', 'seniority', 'location',
  'work_mode', 'start_date', 'duration_months', 'job_description', 'must_have_skills'];
// client_budget celowo pominięty: pusty, gdy klient prosi o naszą stawkę

const isEmpty = v => v === '' || v === null || v === undefined || v === 0 ||
  (Array.isArray(v) && v.length === 0);

const reported = new Set(out.missing_info.map(m => m.field));
for (const f of REQUIRED) {
  if (isEmpty(out[f]) && !reported.has(f)) {
    out.missing_info.push({
      field: f,
      question: `Please provide: ${f.replace(/_/g, ' ')}`,
    });
  }
}

return [{ json: { output: out } }];
